tape( 'the function supports view offsets', function test( t ) {
	var expected;
	var out0;
	var out1;
	var x0;
	var x1;

	x0 = new Float64Array([
		1.0,
		2.0, // 0
		3.0,
		4.0, // 1
		5.0,
		6.0  // 2
	]);
	out0 = new Float64Array([
		7.0,
		0.0, // 0
		0.0, // 1
		0.0, // 2
		8.0
	]);
	expected = new Float64Array([
		7.0,
		2.0, // 0
		4.0, // 1
		6.0, // 2
		8.0
	]);

	x1 = new Float64Array( x0.buffer, x0.BYTES_PER_ELEMENT * 1 );
	out1 = new Float64Array( out0.buffer, out0.BYTES_PER_ELEMENT * 1 );

	maxk( 3, 3, x1, 2, out1, 1 );

	t.deepEqual( out0, expected, 'returns expected value' );
	t.end();
});
